 const clear=()=>{cardRequestSequence.current+=1;cardScope.current=null;invalidateCardDetail();clearVirtualCardCreate();clearCardReplacement();clearCardRenewal();walletListRequestSequence.current+=1;walletScope.current=null;invalidateWalletDetail();clearWalletOperations();setSession(null);replaceAccounts([]);clearWalletDetail();setCards([]);setCardNextCursor(null);setCardListLoadingMore(false);setCardListError('');setSelectedCard(null);clearCardBalance();clearCardLimits();clearCardTransactions()}
 const loadWalletOperations=async(expectedScope=walletScope.current)=>{clearWalletOperations();const request={requestId:++walletOperationRequestSequence.current,scopeKey:expectedScope,cursor:null};walletOperationCursorTarget.current=null;const isCurrent=()=>walletOperationActivityRequestIsCurrent(request,walletOperationRequestSequence.current,walletScope.current,walletOperationCursorTarget.current);setWalletOperationsLoading(true);try{const page=await walletApi.walletOperations();if(isCurrent())setWalletOperations(page)}catch(value){if(isCurrent()){setWalletOperations(null);setWalletOperationsError(describeWalletOperations(value))}}finally{if(isCurrent())setWalletOperationsLoading(false)}}
 const loadWalletBalanceSummary=async(rows:WalletAccountRecord[],account:WalletAccountRecord|null,sessionEnvironment:WalletSession['environment'],expectedScope=walletScope.current)=>{const request={requestId:++walletBalanceSummaryRequestSequence.current,scopeKey:expectedScope,accountId:account?.id??null,accountsVersion:captureWalletAccountsVersion(rows)};const isCurrent=()=>walletBalanceSummaryRequestIsCurrent(request,walletBalanceSummaryRequestSequence.current,walletScope.current,accountsRef.current,selectedAccountRef.current);setWalletBalanceSummary(null);setWalletBalanceSummaryLoading(true);setWalletBalanceSummaryError('');try{const summary=await walletApi.walletBalanceSummary(sessionEnvironment);if(isCurrent())setWalletBalanceSummary(summary)}catch(value){if(isCurrent())setWalletBalanceSummaryError(describeWalletBalanceSummary(value))}finally{if(isCurrent())setWalletBalanceSummaryLoading(false)}}
 const loadWallet=async(account:WalletAccountRecord,expectedScope=walletScope.current)=>{const request={requestId:++walletAccountRequestSequence.current,scopeKey:expectedScope,accountId:account.id};walletAccountTarget.current=account.id;const historyRequest={requestId:++walletHistoryRequestSequence.current,scopeKey:expectedScope,assetCode:account.assetCode,cursor:null};walletHistoryAssetTarget.current=account.assetCode;walletHistoryCursorTarget.current=null;const isCurrent=()=>walletRequestIsCurrent(request,walletAccountRequestSequence.current,walletScope.current,walletAccountTarget.current);const historyIsCurrent=()=>walletHistoryRequestIsCurrent(historyRequest,walletHistoryRequestSequence.current,walletScope.current,walletHistoryAssetTarget.current,walletHistoryCursorTarget.current);replaceSelectedAccount(account);setAccountBalance(null);clearWalletTransactions();setWalletLoading(true);setWalletHistoryLoading(true);setWalletError('');const[balanceResult,historyResult]=await Promise.all([walletApi.walletBalance(account.id).then(balance=>({balance,error:null})).catch(error=>({balance:null,error})),walletApi.walletTransactions(account.assetCode).then(page=>({page,error:null})).catch(error=>({page:null,error}))]);if(isCurrent()){if(balanceResult.balance)setAccountBalance(balanceResult.balance);else{setAccountBalance(null);setWalletError(describe(balanceResult.error))}setWalletLoading(false)}if(historyIsCurrent()){if(historyResult.page)setWalletTransactions(historyResult.page);else{setWalletTransactions(null);setWalletHistoryError(describe(historyResult.error))}setWalletHistoryLoading(false)}}
 const loadCard=async(card:CardRecord,expectedScope=cardScope.current,callbacks?:{onError?:(value:unknown)=>void;onSettled?:()=>void})=>{cardActionRequestSequence.current+=1;cardActionTarget.current=null;const request={requestId:++cardDetailRequestSequence.current,scopeKey:expectedScope,cardId:card.id};cardDetailTarget.current=card.id;const balanceRequest={requestId:++cardBalanceRequestSequence.current,scopeKey:expectedScope,cardId:card.id};cardBalanceTarget.current=card.id;const limitsRequest={requestId:++cardLimitsRequestSequence.current,scopeKey:expectedScope,cardId:card.id};cardLimitsTarget.current=card.id;const transactionRequest={requestId:++cardTransactionRequestSequence.current,scopeKey:expectedScope,cardId:card.id};cardTransactionTarget.current=card.id;const isCurrent=()=>cardRequestIsCurrent(request,cardDetailRequestSequence.current,cardScope.current,cardDetailTarget.current);const balanceIsCurrent=()=>cardBalanceRequestIsCurrent(balanceRequest,cardBalanceRequestSequence.current,cardScope.current,cardBalanceTarget.current);const limitsIsCurrent=()=>cardLimitsRequestIsCurrent(limitsRequest,cardLimitsRequestSequence.current,cardScope.current,cardLimitsTarget.current);const transactionIsCurrent=()=>cardRequestIsCurrent(transactionRequest,cardTransactionRequestSequence.current,cardScope.current,cardTransactionTarget.current);setCardBalance(null);setCardBalanceLoading(true);setCardBalanceError('');setCardLimits(null);setCardLimitsLoading(true);setCardLimitsError('');try{const[detailResult,balanceResult,limitsResult,transactionResult]=await Promise.all([walletApi.card(card.id).then(detail=>({detail,error:null})).catch(error=>({detail:null,error})),walletApi.balance(card.id).then(balance=>({balance,error:null})).catch(error=>({balance:null,error})),walletApi.limits(card.id).then(limits=>({limits,error:null})).catch(error=>({limits:null,error})),walletApi.transactions(card.id).then(page=>({page,error:null})).catch(error=>({page:null,error}))]);if(balanceIsCurrent()){if(balanceResult.balance)setCardBalance(balanceResult.balance);else{setCardBalance(null);setCardBalanceError(describeCardBalance(balanceResult.error))}setCardBalanceLoading(false)}if(limitsIsCurrent()){if(limitsResult.limits)setCardLimits(limitsResult.limits);else{setCardLimits(null);setCardLimitsError(describeCardLimits(limitsResult.error))}setCardLimitsLoading(false)}if(transactionIsCurrent()){if(transactionResult.page){setCardTransactions(transactionResult.page.transactions);setCardTransactionNextCursor(transactionResult.page.nextCursor);setCardTransactionError('')}else{setCardTransactions([]);setCardTransactionNextCursor(null);setCardTransactionError(describe(transactionResult.error))}}if(!isCurrent())return;if(!detailResult.detail)throw detailResult.error;setSelectedCard(detailResult.detail);setCards(current=>current.map(row=>row.id===detailResult.detail?.id?detailResult.detail:row))}catch(value){if(!isCurrent())return;if(callbacks?.onError)callbacks.onError(value);else throw value}finally{if(isCurrent())callbacks?.onSettled?.()}}
 const acceptSession=async(current:WalletSession)=>{if(current.environment!==walletRuntime.environment)throw new Error(`Build environment ${walletRuntime.environment} does not match session ${current.environment}`);const scope=walletTransferSessionScope(current,walletRuntime.environment);if(!scope)throw new Error('Session is expired or unavailable for this non-production Wallet');cardScope.current=scope;walletScope.current=scope;invalidateCardDetail();clearVirtualCardCreate();clearCardReplacement();clearCardRenewal();invalidateWalletDetail();clearWalletOperations();const cardRequestId=++cardRequestSequence.current;const walletListRequestId=++walletListRequestSequence.current;setCards([]);setCardNextCursor(null);setCardListError('');setSelectedCard(null);clearCardBalance();clearCardLimits();clearCardTransactions();replaceAccounts([]);clearWalletDetail();const[cardPage,accountRows]=await Promise.all([walletApi.cards(),walletApi.walletAccounts(current)]);if(!walletTransferSessionScope(current,walletRuntime.environment)||cardScope.current!==scope||cardRequestSequence.current!==cardRequestId||walletScope.current!==scope||walletListRequestSequence.current!==walletListRequestId)return;setSession(current);setCards(cardPage.cards);setCardNextCursor(cardPage.nextCursor);replaceAccounts(accountRows);const card=cardPage.cards[0]||null;const account=accountRows[0]||null;setSelectedCard(card);replaceSelectedAccount(account);await Promise.all([card?loadCard(card,scope):Promise.resolve(),account?loadWallet(account,scope):Promise.resolve(),loadWalletBalanceSummary(accountRows,account,current.environment,scope),loadWalletOperations(scope)])}
 const loadMoreCards=async()=>{if(!session||!cardNextCursor||cardListLoadingMore)return;const scope=sessionScope(session);if(scope!==cardScope.current)return;const cursor=cardNextCursor;const requestId=++cardRequestSequence.current;setCardListLoadingMore(true);setCardListError('');try{const page=await walletApi.cards(cursor);if(cardScope.current!==scope||cardRequestSequence.current!==requestId)return;setCards(current=>mergeCardPages(current,page.cards));setCardNextCursor(page.nextCursor)}catch(value){if(cardScope.current===scope&&cardRequestSequence.current===requestId)setCardListError(describe(value))}finally{if(cardScope.current===scope&&cardRequestSequence.current===requestId)setCardListLoadingMore(false)}}
 const loadMoreCardTransactions=async()=>{if(!session||!selectedCard||!cardTransactionNextCursor||cardTransactionLoadingMore)return;const scope=sessionScope(session);const cardId=selectedCard.id;if(scope!==cardScope.current||cardId!==cardDetailTarget.current||cardId!==cardTransactionTarget.current)return;const cursor=cardTransactionNextCursor;const request={requestId:++cardTransactionRequestSequence.current,scopeKey:scope,cardId};cardTransactionTarget.current=cardId;const isCurrent=()=>cardRequestIsCurrent(request,cardTransactionRequestSequence.current,cardScope.current,cardTransactionTarget.current)&&cardId===cardDetailTarget.current;setCardTransactionLoadingMore(true);setCardTransactionError('');try{const page=await walletApi.transactions(cardId,cursor);if(!isCurrent())return;setCardTransactions(current=>mergeCardTransactionPages(current,page.transactions));setCardTransactionNextCursor(page.nextCursor)}catch(value){if(isCurrent())setCardTransactionError(describe(value))}finally{if(isCurrent())setCardTransactionLoadingMore(false)}}
